def check_year(rel, t, y, txt, has_text):
    probs = []
    if y:
        if not re.fullmatch(r"\d{4}", y): probs.append(f"y={y!r} not 4 digits")
        elif not 1500 <= int(y) <= 2026: probs.append(f"y={y} out of range")
        elif y not in rel and not (txt and (y in txt or re.search(r"\b\d{1,2}[/-](?:\d{1,2}[/-])?" + y[2:] + r"\b|'" + y[2:] + r"\b", txt))):   # 2-digit date forms 7/98, 3-08, 11/27/05, '08 (RT2 #174)
            probs.append(f"y={y} not in text/filename" + ("" if has_text else " (no text layer)"))
    tyears = [m for g in M.YEAR_IN_PARENS.findall(t) for m in M.YR.findall(g)]
    if tyears and y not in tyears:
        probs.append(f"title paren year {tyears} != y={y!r} (filename years {M.YR.findall(os.path.basename(rel))})")
    return probs

# RT3 #184: the vote has no Norwegian, Swedish or Nepali of its own: Bokmål and Swedish stopwords vote "da", Devanagari
# votes "hi". A vote for the sibling is not a conflict; any other vote still is.
SIBLING = {"nb": {"da"}, "sv": {"da"}, "ne": {"hi"}}

def check_lang(l, s, a, txt, has_text):
    probs = []
    if l not in M.ISO6391: probs.append(f"l={l!r} not ISO 639-1")
    ok = {l} | SIBLING.get(l, set())
    nonlatin = l in M.NONLATIN or "hi" in SIBLING.get(l, set())
    if has_text:
        tv, td = M.vote(txt[:200000], 100)
        if tv and tv not in ok and not (nonlatin and tv not in M.NONLATIN):   # legacy-font ASCII text layer: vote meaningless
            probs.append(f"text votes {tv} {td}")
    for fld, val in (("s", s), ("a", a)):
        v, d = M.vote(val, 2)
        if v and v not in ok: probs.append(f"{fld} written in {v} {d}")
    if l == "vi" and (len(M.VNI.findall(s)) >= 3 or len(M.VNI.findall(a)) >= 3): probs.append("VNI mojibake in s/a")
    return probs

def check_dose(t, s, a):
    return [f"{fld}:'{m.group(0)}'" for fld, val in (("t", t), ("s", s), ("a", a)) for m in DOSE.finditer(M.MANUAL_NO.sub(" ", val))]

def check_echo(l, s, a):
    probs = []
    for fld, val in (("s", s), ("a", a)):
        if not val.strip(): continue
        m = M.ECHO.search(val)
        if m: probs.append(f"{fld} pattern '{m.group(0)}'")
        if not M.TERMINAL.search(val.strip()): probs.append(f"{fld} no terminal punctuation")
        if len(val.split()) < 5 and l not in M.NONLATIN: probs.append(f"{fld} fragment ({len(val.split())} words)")
        if M.MOJI.search(val): probs.append(f"{fld} mojibake")
        if l == "bn" and M.BN_GARBLE.search(val): probs.append(f"{fld} garbled Bengali (legacy-font extraction)")
    if "?" in s: probs.append("s is a question")
    if a.count("?") >= 2: probs.append("a is a question list")
    return probs

def check_empty(s, a, c1=""):
    """#285 (round 11 C1): a field C1 emptied (listed in the entry's "c1") is a removal, not a lost summary"""
    return [f"{fld} empty" for fld, val in (("s", s), ("a", a)) if not val.strip() and fld not in c1]

def check_c1(s, a, c1=""):
    """#285 (round 11 class 8, C1): no s/a sentence holds a digit (the historical warning line keeps its year), and a
    field marked as C1-emptied is empty"""
    return ([f"{fld}: digit sentence '{x[:80]}'" for fld, val in (("s", s), ("a", a)) for x in G.c1_sentences(val)
             if G.has_num(x) and not G.C1_HIST.match(x)]
            + [f"{fld} marked c1 but not empty" for fld, val in (("s", s), ("a", a)) if fld in c1 and val.strip()])

def check_audience(rel, t, s, a, txt=None):
    probs = [] if G.surv_path(rel, t) else [f"{fld}:'{m.group(0)}'" for fld, val in (("t", t), ("s", s), ("a", a))
                                            for m in [G.SURV_AUD.search(val)] if m]   # RT5 #205: every shelf
    probs += [f"{fld}:'{m.group(0)}'" for fld, val in (("s", s), ("a", a)) for m in [G.READ_YEAR.search(val)] if m]   # RT6 L5
    if not G.surv_path(rel, t):
        probs += [f"{fld}:'{m.group(0)}'" for fld, val in (("s", s), ("a", a)) for m in [G.SURV_READER.search(val)] if m]
    ft = G.ftext(G.clean_text(txt)) if txt else None   # RT10 M4 (#205, s17): the framing phrase must be in the document text,
    probs += [f"{fld}:frame '{x}' not in text" for fld, val in (("s", s), ("a", a)) for x in [G.frame_bad(val, ft) if ft else ""] if x]
    if rel.startswith(M.SURV_OK_SHELVES) or "surviv" in t.lower(): return probs   # every shelf (gen_doc_answers.surv_bad)
    return probs + [f"{fld}:'{m.group(0)}'" for fld, val in (("t", t), ("s", s), ("a", a)) for m in [M.SURV.search(val)] if m]

# RT5 #203 (class 6, b1judge2): s/a written from the publisher's back-list ads ("model boats, electric bells, bamboo work,
# taxidermy" on Rustic Carpentry). Ad pages: in the first/last 15 pages, 3+ ad markers (gen_doc_answers.AD plus the
# Handicraft Series layout). A content word (5+ letters, not in t) is ad-only when it is on an ad page and on at most one
# other page. Documents under 40 pages are skipped (a short play's every page sits in the 15-page windows).
AD_PAGE = re.compile(G.AD.pattern + r"|series\s*\(continued\)|with (?:\d+|numerous) (?:engravings|illustrations)|contents\.\s*[—-]", re.I)
WORD5 = re.compile(r"[^\W\d_]{5,}")

def check_front(t, s, a, txt):
    pages = (txt or "").split("\f")
    n = len(pages)
    if n < 40: return []
    ads = {i for i in list(range(min(15, n))) + list(range(max(15, n - 15), n)) if len(AD_PAGE.findall(pages[i])) >= 3}
    if not ads: return []
    tw = set(WORD5.findall(t.lower()))
    pl = [p.lower() for p in pages]
    words = [w for w in dict.fromkeys(WORD5.findall((s + " " + a).lower())) if w not in tw]
    hits = {w: [i for i, p in enumerate(pl) if w in p] for w in words}
    intext = [w for w in words if hits[w]]
    ad_only = [w for w in intext if any(i in ads for i in hits[w]) and sum(i not in ads for i in hits[w]) <= 1]
    return [f"ad-page words {ad_only}"] if len(ad_only) >= 3 and len(ad_only) >= 0.4 * len(intext) else []

# RT4 #195 (class 6): conversion manuals told private owners to "attempt the conversion" / "restore select-fire"; the
# documents say licensed manufacturers only, a felony otherwise. On a firearms path, an entry about MAKING an NFA item
# (machine gun, select fire, silencer, grenade launcher) must carry a legal line and no private-owner audience sentence.
NFA = re.compile(r"full[- ]?auto|select[- ]?fire|fully automatic|automatic (?:fire|weapon)|sub-?machine ?guns?|machine ?guns?|"
                 r"machine pistols?|silencers?|suppressors?|grenade launchers?", re.I)
MAKE = re.compile(r"\b(?:conver\w*|modif\w*|build\w*|construct(?!ion)\w*|manufactur\w*|fabricat\w*|mak(?:e|es|ing)|restor\w*|"
                  r"replicat\w*|recreat\w*|improvis\w*|upgrad\w*|alter\w*)\b", re.I)
PRIV = re.compile(r"\b(?:gun owners?|owners?|collectors?|individuals?|enthusiasts?|hobbyists?|builders?|DIY|people|anyone|"
                  r"insurgents|guerrillas|users?)\b", re.I)
LEGAL = re.compile(r"licen[cs]|illegal|felony|federal law|unlawful|\bB?ATF\b|Bureau of Alcohol", re.I)
SENT = re.compile(r"(?<=[.!])\s+")

def check_legal(rel, t, s, a):
    if not re.search(r"firearm|weapon|gun", rel, re.I): return []
    if not any(NFA.search(x) and MAKE.search(x) for v in (t, s, a) for x in SENT.split(v)): return []
    probs = [f"private-owner wording '{x[:80]}'" for x in SENT.split(s + " " + a) if PRIV.search(x) and not LEGAL.search(x)]
    if not LEGAL.search(s + " " + a): probs.append("no legal line (licence / felony / federal law)")
    return probs

# ---- RT6 L5: the b1mech gaps c5, c7, c9, c1 (see the docstring) ----
def core_title(t):
    return " ".join(re.sub(r"[^\w]+|\d+|_", " ", re.sub(r"\([^()]*\)", " ", (t or "").casefold())).split())

def stem_words(rel):
    return {w for w in re.split(r"[^a-z]+", os.path.splitext(os.path.basename(rel))[0].lower()) if len(w) >= 4}

def copied_index(cat):
    idx = {}
    for k, v in cat.items():
        c = core_title(v.get("t"))
        if c: idx.setdefault(c, []).append(k)
    return idx

def check_copied(rel, t, idx):
    if rel in SAME_WORK: return []
    ps = [q for q in idx.get(core_title(t), []) if q != rel]
    if not ps or any(os.path.dirname(q) == os.path.dirname(rel) or stem_words(q) & stem_words(rel) for q in ps): return []
    return [f"title also on {q}" for q in ps][:2]


def check_slug(rel, t):
    if rel in SLUG_OK: return []
    body = re.sub(r"\([^()]*\)", " ", t or "").strip()
    words = re.findall(r"[^\s,:;]+", body)
    stem = os.path.splitext(os.path.basename(rel))[0].lower()
    if not words or not all(w.lower().strip(".") in stem for w in words): return []
    why = [f"code {w}" for w in words if re.fullmatch(r"(?i)[a-z]{3,}\d{3,}[a-z]*|\d{3,}[a-z]{3,}", w)]
    why += [f"caps {w}" for w in words if re.fullmatch(r"[A-Z]{6,}", w)]   # real acronyms (UNICEF, MATLAB) are in SLUG_OK
    why += [f"language code {w}" for w in words if w in ("En", "Sp", "Es", "Fr", "Pt")]
    if body[:1].islower(): why.append("starts lower case")
    return why

YCLAIM = re.compile(r"(?<![\d.,/-])(1[5-9]\d\d|20[0-2]\d)(?![\d.,/-]|s\b|’s|'s)")

def check_yearclaim(rel, t, y, s, a, src, txt, has_text):
    if src == "vl" or not has_text: return []
    return [f"{fld}: {yr} not in text" for fld, val in (("s", s), ("a", a)) for yr in sorted(set(YCLAIM.findall(val)))
            if yr != y and yr not in t and yr not in rel and yr not in txt]

IMPRINT = re.compile(r"(?:©|\(c\)|copyright|copr\.|entered according to act of congress,? in the year|derechos reservados|"
                     r"published in|first published|publicado en)\D{0,40}?(1[5-9]\d\d|20[0-2]\d)(?!\d)", re.I)

def check_fileyear(rel, y, txt, has_text):
    if not (has_text and re.fullmatch(r"\d{4}", y or "") and y in os.path.basename(rel)) or re.search(r"(?<!\d)%s(?!\d)" % y, txt):
        return []
    imp = sorted(set(IMPRINT.findall("\f".join(txt.split("\f")[:10]))) - {y})
    return [f"y={y} only in the file name; front pages print {imp}"] if imp else []

def main():
    cat = {k: v for k, v in json.load(open(CATALOG)).items() if not k.startswith("_")}
    idx = copied_index(cat)
    print("entries", len(cat), flush=True)
    tmp = OUT + ".tmp"; n = {"PASS": 0, "FAIL": 0, "SKIP": 0, "NOTE": 0}
    with open(tmp, "w", newline="") as f:
        w = csv.writer(f, lineterminator="\n")
        for i, (rel, v) in enumerate(sorted(cat.items())):
            if i % 1000 == 0: print("progress", i, flush=True)
            t, y, l, s, a = (str(v.get(x) or "") for x in "tylsa")
            try: txt = M.text_of(rel)
            except Exception: txt = None
            has_text = bool(txt) and len(txt.split()) > 200
            for check, probs in (("year", check_year(rel, t, y, txt, has_text)), ("lang", check_lang(l, s, a, txt, has_text)),
                                 ("dose", check_dose(t, s, a)), ("echo", check_echo(l, s, a)), ("audience", check_audience(rel, t, s, a, txt)),
                                 ("empty", check_empty(s, a, v.get("c1", ""))), ("c1", check_c1(s, a, v.get("c1", ""))), ("legal", check_legal(rel, t, s, a)), ("front", check_front(t, s, a, txt)),
                                 ("copied", check_copied(rel, t, idx)), ("slug", check_slug(rel, t)),
                                 ("yearclaim", check_yearclaim(rel, t, y, s, a, v.get("src", ""), txt or "", has_text)),
                                 ("fileyear", check_fileyear(rel, y, txt or "", has_text))):
                st, detail = ("FAIL", "; ".join(probs)) if probs else ("PASS", "")
                hand = DROP.get((rel, check)) or NOTE.get((rel, check)) or SKIP.get((rel, check))
                if st == "FAIL" and hand: st, detail = "SKIP", f"hand-checked 2026-10-09: {hand}"
                if st == "FAIL" and check == "fileyear": st = "NOTE"   # RT6 L5: counted for the next round, never a FAIL
                w.writerow(["t9", check, rel, st, detail[:300]]); n[st] += 1
                if st == "FAIL": print(check, rel, detail[:160], flush=True)
    os.replace(tmp, OUT)
    print("done t9_catalog", n, flush=True)

if __name__ == "__main__":
    main()
